import {
  buildClassificationDocument,
  classifyText,
  warmupClassifier,
} from "./classifier.js";
import {
  knownMentionIds,
  mentionUrl,
  saveMention,
  type MentionRecord,
} from "./store.js";
import type { XPost, XUser } from "./x-client.js";

/** Raw post payload accepted by POST /api/ingest (mirrors SearchedPost). */
export type IngestPost = {
  post: XPost;
  author?: XUser;
  queryId?: string;
};

export type IngestResult = {
  received: number;
  saved: number;
  classified: number;
  skipped: number;
  errors: string[];
};

/**
 * Classify + dedup + persist posts pushed by the stateless scanner.
 * The web service owns the model and the (volume-backed) store.
 */
export async function ingestPosts(items: IngestPost[]): Promise<IngestResult> {
  await warmupClassifier();
  const known = knownMentionIds();
  let classified = 0;
  let saved = 0;
  let skipped = 0;
  const errors: string[] = [];

  for (const item of items) {
    const post = item?.post;
    if (!post?.id || !post.text) {
      skipped++;
      continue;
    }
    if (known.has(post.id)) {
      skipped++;
      continue;
    }
    try {
      const classification = await classifyText(
        buildClassificationDocument({
          text: post.text,
          authorName: item.author?.name,
          authorUsername: item.author?.username,
          authorBio: item.author?.description,
        }),
      );
      classified++;
      const record: MentionRecord = {
        id: post.id,
        text: post.text,
        createdAt: post.created_at,
        url: mentionUrl(item.author?.username, post.id),
        queryId: item.queryId ?? "push",
        author: item.author
          ? {
              id: item.author.id,
              username: item.author.username,
              name: item.author.name,
              bio: item.author.description,
              followers: item.author.public_metrics?.followers_count,
            }
          : undefined,
        metrics: post.public_metrics
          ? {
              likes: post.public_metrics.like_count,
              replies: post.public_metrics.reply_count,
              reposts: post.public_metrics.retweet_count,
              quotes: post.public_metrics.quote_count,
              impressions: post.public_metrics.impression_count,
            }
          : undefined,
        classification,
        scannedAt: new Date().toISOString(),
      };
      saveMention(record);
      known.add(post.id);
      saved++;
    } catch (err) {
      if (errors.length < 5) errors.push(`${post.id}: ${String(err)}`);
    }
  }

  return { received: items.length, saved, classified, skipped, errors };
}

