export async function handleRequest(req: IncomingMessage, res: ServerResponse) {
  const host = req.headers.host || "127.0.0.1";
  const url = new URL(req.url || "/", `http://${host}`);
  const window = parseWindow(url.searchParams.get("window"));
  const q = url.searchParams.get("q") ?? "";
  const bucket = parseBucket(url.searchParams.get("bucket"));

  if (url.pathname === "/api/ingest") {
    await handleIngest(req, res);
    return;
  }

  const mentions = loadMentions();
  const query = { window, q, bucket: bucket || undefined };

  if (url.pathname === "/api/feed") {
    const feed = filterFeed(mentions, query);
    send(res, 200, JSON.stringify({ window, count: feed.length, posts: feed }), "application/json; charset=utf-8");
    return;
  }
  if (url.pathname === "/api/leaderboard") {
    const board = rankLeaderboard(mentions, query);
    send(res, 200, JSON.stringify({ window, count: board.length, accounts: board }), "application/json; charset=utf-8");
    return;
  }

  if (url.pathname !== "/" && url.pathname !== "/leaderboard") {
    send(res, 404, "Not found", "text/plain; charset=utf-8");
    return;
  }

  const view = url.pathname === "/leaderboard" ? "leaderboard" : "feed";
  const feed = filterFeed(mentions, query);
  const board = rankLeaderboard(mentions, query);
  const html = renderPage({
    view,
    window,
    q,
    bucket,
    feed,
    board,
    counts: windowCounts(mentions),
    totalStored: mentions.length,
    noiseHidden: mentions.filter(isNoise).length,
  });
  send(res, 200, html, "text/html; charset=utf-8");
}

