/**
 * Meteora ecosystem recent-search queries for X API v2.
 * Keep each query under ~512 chars (Basic/Pro recent search limit).
 *
 * Four tiers: STRICT = high-precision builder/BD signals; SEMANTIC = broad
 * anchor-only nets that let the BGE classifier do the filtering (no
 * secondary keyword groups, all languages); PAD_WATCH = every meteora.fyi
 * launchpad; MEMES = ecosystem culture. The hourly monitor scans all tiers.
 *
 * All queries are language-agnostic (no lang: filter) so non-English
 * discourse is discovered. The classifier (bge-small-en-v1.5) is
 * English-only — non-English posts mostly land in the noise gate (safe,
 * just won't appear in the feed). A multilingual model would improve this.
 */
const STRICT_QUERIES: { id: string; query: string; note: string }[] = [
  {
    id: "dbc_sdk",
    note: "DBC + SDK/config/partner language",
    query:
      '("Dynamic Bonding Curve" OR DBC) (SDK OR CPI OR config OR partner OR PoolConfig) (Meteora OR @MeteoraAG) -is:retweet',
  },
  {
    id: "launchpad_build",
    note: "Launchpads building / integrating",
    query:
      '(launchpad OR "fun launch" OR Invent OR scaffold) (Meteora OR @MeteoraAG) (DBC OR DAMM OR integrate OR building OR shipped) -is:retweet',
  },
  {
    id: "damm_migrate",
    note: "DAMM graduation / migration tech",
    query:
      '("DAMM v2" OR DAMMv2 OR "DAMM") (migrate OR graduate OR "locked LP" OR launchpad) (Meteora OR @MeteoraAG OR DBC) -is:retweet',
  },
  {
    id: "dlmm_integrate",
    note: "DLMM builder talk",
    query:
      '(DLMM OR "bin step" OR "price bins") (SDK OR CPI OR integrate OR building) (Meteora OR @MeteoraAG) -is:retweet',
  },
  {
    id: "docs_sdk_pkg",
    note: "Docs / npm package mentions",
    query:
      '("dynamic-bonding-curve-sdk" OR "@meteora-ag/dynamic-bonding-curve" OR docs.meteora.ag) -is:retweet',
  },
  {
    id: "help_partner",
    note: "Teams wanting help / partnership",
    query:
      '(Meteora OR @MeteoraAG OR DBC) (launchpad) (help OR partner OR integrate OR "looking for" OR "anyone using" OR support) -is:retweet',
  },
  {
    id: "builder_shipped",
    note: "Shipped / building signals",
    query:
      '(building OR integrating OR "we shipped" OR "built on" OR "just shipped") (Meteora) (launchpad OR DBC OR DLMM OR DAMM OR SDK) -is:retweet',
  },
  {
    id: "vertical_quote",
    note: "Token-2022 / RWA / quote verticals",
    query:
      '("Token-2022" OR "transfer hook" OR RWA OR xStocks OR "quote mint") (Meteora OR DBC OR "bonding curve") -is:retweet',
  },
];

/**
 * Semantic broad nets — anchor on Meteora ecosystem terms only, no
 * secondary keyword groups, all languages. The BGE classifier's noise
 * gate filters the hype these inevitably pull. This is the "semantic
 * discovery" tier: cast wide, let embeddings decide.
 */
const SEMANTIC_QUERIES: { id: string; query: string; note: string }[] = [
  {
    id: "semantic_meteora",
    note: "Anything mentioning Meteora + core tech terms (all languages)",
    query:
      '(Meteora OR @MeteoraAG OR @MeteoraEco) (DBC OR "bonding curve" OR DAMM OR DLMM OR launchpad OR Invent OR "Alpha Vault" OR graduation) -is:retweet',
  },
  {
    id: "semantic_dbc_damm",
    note: "DBC / DAMM / DLMM mentions without requiring Meteora keyword (all languages)",
    query:
      '("Dynamic Bonding Curve" OR DBC OR "DAMM v2" OR DAMMv2 OR DLMM OR "dynamic-bonding-curve") -is:retweet',
  },
  {
    id: "semantic_meteora_url",
    note: "Posts linking to meteora.ag or mentioning Invent (all languages)",
    query:
      '(url:meteora.ag OR "Meteora Invent" OR (Invent Meteora) OR meteora.fyi) -is:retweet',
  },
];

/** Official Meteora accounts — all languages by nature (from: queries). */
const OFFICIAL_QUERIES: { id: string; query: string; note: string }[] = [
  {
    id: "official",
    note: "Official Meteora accounts",
    query: "(from:MeteoraAG OR from:MeteoraEco) -is:retweet",
  },
];

/**
 * Per-pad watch tier — every launchpad listed on meteora.fyi (the DBC
 * ecosystem screener). Meteora-free on purpose: drama about a pad rarely
 * mentions Meteora. Domains + distinctive names keep generic words
 * ("Bags", "Ethics") from matching junk. Batched 3-per-query for credits.
 */
const PAD_WATCH_QUERIES: { id: string; query: string; note: string }[] = [
  {
    id: "pad_watch_a",
    note: "Ember Curve · LFOwn · Bags",
    query:
      '("Ember Curve" OR embercurve.fun OR LFOwn OR letsfuckingown.fun OR letsfuckingown OR bags.fm OR "Bags pad") -is:retweet',
  },
  {
    id: "pad_watch_b",
    note: "Perpspad · ClawPump · StonkOptions",
    query:
      "(Perpspad OR perpspad.fun OR ClawPump OR clawpump.tech OR StonkOptions OR star.fun) -is:retweet",
  },
  {
    id: "pad_watch_c",
    note: "Ethics · RevShare · OTC Desks",
    query:
      '(ethics.ltd OR "Ethics pad" OR "Ethics launchpad" OR revshare.dev OR "RevShare launchpad" OR otcdesks.cash OR "OTC Desks") -is:retweet',
  },
];

/** Ecosystem meme/culture tier — jokes, shitposts, templates about Meteora tech. */
const MEME_QUERIES: { id: string; query: string; note: string }[] = [
  {
    id: "memes_ecosystem",
    note: "Memes / shitposts about Meteora DBC / DAMM / DLMM / ecosystem",
    query:
      '(meme OR memes OR shitpost OR "copium" OR "cope") (Meteora OR DBC OR DAMM OR DLMM OR "Ember Curve" OR "bonding curve" OR graduation) -is:retweet',
  },
];

/** Standing pool for `npm run scan` and the hourly push-scan cron. */
export const SEARCH_QUERIES: { id: string; query: string; note: string }[] = [
  ...STRICT_QUERIES,
  ...SEMANTIC_QUERIES,
  ...OFFICIAL_QUERIES,
  ...PAD_WATCH_QUERIES,
  ...MEME_QUERIES,
