const PAGE_SIZE = 50;

export async function handleRequest(req: IncomingMessage, res: ServerResponse) {
  const host = req.headers.host || "127.0.0.1";
  const url = new URL(req.url || "/", `http://${host}`);
  const window = parseWindow(url.searchParams.get("window"));
  const lane = parseLane(url.searchParams.get("lane"));
  const postType = parsePostType(url.searchParams.get("type"));
  const q = url.searchParams.get("q") ?? "";
  const bucket = parseBucket(url.searchParams.get("bucket"));
  const page = Math.max(1, Number(url.searchParams.get("page") ?? 1));
  if (url.pathname === "/api/ingest") {
    await handleIngest(req, res);
    return;
  }
  if (url.pathname === "/api/export") {
    handleExport(req, res);
    return;
  }

  const mentions = loadMentions();
  const query = { window, q, bucket: bucket || undefined, lane, postType };

  if (url.pathname === "/api/feed") {
    const feed = filterFeed(mentions, query);
    send(res, 200, JSON.stringify({ window, lane, postType, count: feed.length, posts: feed }), "application/json; charset=utf-8");
    return;
  }
  if (url.pathname === "/api/leaderboard") {
    // Leaderboard is always the ecosystem lead board (no official accounts).
    const board = rankLeaderboard(mentions, { window, q, bucket: bucket || undefined });
    send(res, 200, JSON.stringify({ window, count: board.length, accounts: board }), "application/json; charset=utf-8");
    return;
  }

  if (url.pathname !== "/" && url.pathname !== "/leaderboard") {
    send(res, 404, "Not found", "text/plain; charset=utf-8");
    return;
  }

  const view = url.pathname === "/leaderboard" ? "leaderboard" : "feed";
  const allFeed = filterFeed(mentions, query);
  const totalPages = Math.max(1, Math.ceil(allFeed.length / PAGE_SIZE));
  const safePage = Math.min(page, totalPages);
  const feed = allFeed.slice((safePage - 1) * PAGE_SIZE, safePage * PAGE_SIZE);
  const board = rankLeaderboard(mentions, { window, q, bucket: bucket || undefined });
  const html = renderPage({
    view,
    window,
    lane,
    postType,
    q,
    bucket,
    feed,
    board,
    counts: windowCounts(mentions, new Date(), false, lane, postType),
    officialCount: mentions.filter((m) => isOfficial(m) && !isNoise(m)).length,
    totalStored: mentions.length,
    noiseHidden: mentions.filter(isNoise).length,
    page: safePage,
    totalPages,
    totalFeed: allFeed.length,
  });
  send(res, 200, html, "text/html; charset=utf-8");
}

