  --bg: #0c0d0a;
  --ink: #e8eadf;
  --muted: #9aa18a;
  --line: #2a2d22;
  --card: #14160f;
  --acid: #d4ff4a;
  --acid-ink: #14160f;
  --focus: #9ad4ff;
}
* { box-sizing: border-box; }
html, body { margin: 0; background: var(--bg); color: var(--ink); font-family: "IBM Plex Sans", system-ui, sans-serif; }
a { color: inherit; }
.skip { position: absolute; left: -999px; }
.skip:focus { left: 12px; top: 12px; background: var(--acid); color: var(--acid-ink); padding: 8px 12px; z-index: 9; }
.sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }
.top { display: flex; justify-content: space-between; align-items: flex-end; gap: 16px; padding: 28px 22px 12px; max-width: 1100px; margin: 0 auto; }
.kicker { margin: 0; font-family: "IBM Plex Mono", monospace; font-size: 11px; letter-spacing: 0.16em; text-transform: uppercase; color: var(--muted); }
h1 { margin: 4px 0 0; font-size: clamp(28px, 6vw, 52px); letter-spacing: -0.04em; line-height: 0.9; }
h1 a { text-decoration: none; }
nav { display: flex; gap: 8px; }
nav a { min-height: 40px; display: inline-flex; align-items: center; padding: 0 14px; border: 1px solid var(--line); text-decoration: none; font-size: 14px; }
nav a[aria-current="page"] { background: var(--acid); color: var(--acid-ink); border-color: var(--acid); }
nav a:focus-visible, .chip:focus-visible, button:focus-visible, input:focus-visible, .card-link:focus-visible, table a:focus-visible {
  outline: 2px solid var(--focus); outline-offset: 2px;
}
.ticker { overflow: hidden; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.ticker-track { display: flex; gap: 40px; white-space: nowrap; padding: 10px 0; font-family: "IBM Plex Mono", monospace; font-size: 12px; letter-spacing: 0.12em; color: var(--muted); animation: marquee 28s linear infinite; }
.ticker-track span::after { content: " / "; color: var(--acid); }
@keyframes marquee { from { transform: translateX(0); } to { transform: translateX(-50%); } }
@media (prefers-reduced-motion: reduce) {
  .ticker-track { animation: none; }
  .card { transition: none; }
}
.stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1px; background: var(--line); max-width: 1100px; margin: 0 auto; border: 1px solid var(--line); }
.stats div { background: var(--bg); padding: 16px 18px; }
.stat-label { display: block; font-size: 11px; text-transform: uppercase; letter-spacing: 0.12em; color: var(--muted); font-family: "IBM Plex Mono", monospace; }
.stats strong { font-size: 28px; }
.filters { max-width: 1100px; margin: 20px auto 8px; padding: 0 22px; display: flex; flex-wrap: wrap; gap: 12px; justify-content: space-between; align-items: center; }
.chips { display: flex; flex-wrap: wrap; gap: 8px; }
.chips.wrap { max-width: 1100px; margin: 0 auto 12px; padding: 0 22px; }
.chip { min-height: 40px; display: inline-flex; align-items: center; gap: 8px; padding: 0 12px; border: 1px solid var(--line); text-decoration: none; font-size: 13px; }
.chip span { font-family: "IBM Plex Mono", monospace; color: var(--muted); }
.chip.is-active { background: var(--acid); color: var(--acid-ink); border-color: var(--acid); }
.chip.is-active span { color: var(--acid-ink); }
.chip-sm { min-height: 36px; font-size: 12px; }
.search { display: flex; gap: 8px; }
.search input { min-height: 40px; min-width: 220px; background: var(--card); border: 1px solid var(--line); color: var(--ink); padding: 0 12px; font: inherit; }
.search button { min-height: 40px; padding: 0 14px; background: var(--ink); color: var(--bg); border: 0; font: inherit; cursor: pointer; }
main { max-width: 1100px; margin: 0 auto; padding: 8px 22px 48px; }
.live { font-family: "IBM Plex Mono", monospace; font-size: 12px; letter-spacing: 0.14em; text-transform: uppercase; color: var(--muted); }
.dot { display: inline-block; width: 8px; height: 8px; background: var(--acid); border-radius: 99px; margin-left: 8px; }
/* Masonry: N independent flex columns (bigweek-style). Short cards don't
   stretch to match tall ones — no empty gaps. Falls back to 1 col on mobile. */
.masonry { display: flex; align-items: flex-start; gap: 12px; }
.masonry .col { list-style: none; padding: 0; margin: 0; flex: 1 1 0; min-width: 0; display: flex; flex-direction: column; gap: 12px; }
.card { background: var(--card); border: 1px solid var(--line); border-radius: 8px; transition: border-color 120ms ease; }
.card:has(.card-link:hover) { border-color: rgba(212, 255, 74, 0.45); }
.card-link { display: block; padding: 12px; text-decoration: none; min-height: 40px; border-radius: 8px; }
.card-link header { display: flex; gap: 10px; align-items: center; margin-bottom: 8px; }
.avatar { width: 36px; height: 36px; border-radius: 999px; object-fit: cover; flex: none; }
.avatar-letter { display: grid; place-items: center; background: #222616; color: var(--acid); font-weight: 600; }
.who { flex: 1; display: flex; flex-direction: column; min-width: 0; line-height: 1.25; }
.who strong { font-size: 14px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.meta { color: var(--muted); font-size: 11px; font-family: "IBM Plex Mono", monospace; }
.badge { font-size: 11px; border: 1px solid var(--line); padding: 4px 8px; color: var(--acid); border-radius: 6px; flex: none; }
.card p { margin: 0 0 10px; line-height: 1.45; font-size: 13.5px; white-space: pre-wrap; word-break: break-word; }
.media { display: grid; gap: 6px; margin: 0 0 10px; }
.media.m1 { grid-template-columns: 1fr; }
.media.m2, .media.m3, .media.m4 { grid-template-columns: 1fr 1fr; }
.media img { width: 100%; max-height: 260px; object-fit: cover; border: 1px solid var(--line); border-radius: 6px; background: #000; }
.lane { font-family: "IBM Plex Mono", monospace; text-transform: uppercase; letter-spacing: 0.08em; font-size: 12px; }
/* posts/replies pill toggle (bigweek-style) */
.toggle { display: inline-flex; align-items: center; padding: 3px; border: 1px solid var(--line); border-radius: 999px; background: var(--card); }
.toggle-opt { padding: 6px 18px; border-radius: 999px; font-family: "IBM Plex Mono", monospace; font-size: 12px; text-transform: lowercase; letter-spacing: 0.04em; color: var(--muted); text-decoration: none; transition: background 120ms ease, color 120ms ease; }
.toggle-opt.is-active { background: var(--ink); color: var(--bg); }
.toggle-opt:not(.is-active):hover { color: var(--ink); }
.name-row { display: flex; align-items: center; gap: 4px; min-width: 0; }
.icon { width: 14px; height: 14px; flex: none; }
.name-row .icon { color: var(--acid); }
.card footer.engagement { display: flex; align-items: center; gap: 18px; color: var(--muted); font-size: 11px; font-family: "IBM Plex Mono", monospace; font-variant-numeric: tabular-nums; }
.card footer.engagement > span { display: inline-flex; align-items: center; gap: 5px; }
.card footer.engagement .eng-repost:hover { color: #00ba7c; }
.card footer.engagement .eng-like:hover { color: var(--acid); }
.empty { border: 1px dashed var(--line); padding: 32px; }
.empty h2 { margin-top: 0; }
code { font-family: "IBM Plex Mono", monospace; color: var(--acid); }
.table-wrap { overflow-x: auto; border: 1px solid var(--line); }
table { width: 100%; border-collapse: collapse; }
th, td { text-align: left; padding: 12px; border-bottom: 1px solid var(--line); }
th { font-size: 11px; letter-spacing: 0.12em; text-transform: uppercase; color: var(--muted); }
.rank { font-family: "IBM Plex Mono", monospace; color: var(--acid); width: 40px; }
.sub { color: var(--muted); font-size: 12px; }
footer { max-width: 1100px; margin: 0 auto; padding: 0 22px 40px; color: var(--muted); font-size: 13px; }
/* Pagination */
.pagination { display: flex; align-items: center; justify-content: center; gap: 20px; padding: 24px 0 8px; font-family: "IBM Plex Mono", monospace; font-size: 13px; }
.page-nav { padding: 8px 16px; border: 1px solid var(--line); text-decoration: none; color: var(--ink); border-radius: 6px; transition: border-color 120ms ease; }
.page-nav:hover { border-color: var(--acid); color: var(--acid); }
.page-info { color: var(--muted); }
.page-total { color: var(--muted); opacity: 0.6; }
@media (max-width: 768px) {
  .stats { grid-template-columns: 1fr 1fr; }
  .masonry .col:nth-child(3) { display: none; }
  .top { flex-direction: column; align-items: flex-start; }
}
@media (max-width: 520px) {
  .masonry { flex-direction: column; }
  .masonry .col:nth-child(2) { display: none; }
  .masonry .col:first-child { display: flex; }
}
`;
}

