/**
 * Meteora ecosystem feed — live classified posts from meteora-intel.
 * Renders below the "Build on Meteora DBC" button.
 */

type Post = {
  id: string;
  text: string;
  createdAt?: string;
  url: string;
  author?: {
    username?: string;
    name?: string;
    avatarUrl?: string;
    verified?: boolean;
