  metrics?: {
    likes?: number;
    replies?: number;
    reposts?: number;
    impressions?: number;
  };
  classification: { primary: string; leadScore: number; suppressed: boolean };
  isQuote?: boolean;
  isReply?: boolean;
};

type FeedData = {
  count: number;
  posts: Post[];
  error?: string;
};

