import { NextResponse } from "next/server";

/**
 * Proxy + cache for the Meteora Intel ecosystem feed.
 * Paginates (24/page) so the homepage does not download the full store.
 */

export const dynamic = "force-dynamic";

type FeedPost = {
  id: string;
  text: string;
  createdAt?: string;
  url: string;
  author?: {
    username?: string;
    name?: string;
    avatarUrl?: string;
    verified?: boolean;
  };
  media?: { type: string; url: string }[];
  metrics?: {
    likes?: number;
    replies?: number;
    reposts?: number;
    impressions?: number;
  };
  classification: {
    primary: string;
    leadScore?: number;
    suppressed?: boolean;
  };
  isQuote?: boolean;
  isReply?: boolean;
};

type FeedResponse = {
  window: string;
  lane: string;
  postType: string;
  count: number;
  page?: number;
  limit?: number;
  hasMore?: boolean;
  posts: FeedPost[];
};

const CACHE_TTL_MS = 5 * 60 * 1000;
const cache = new Map<string, { data: FeedResponse; at: number }>();

export async function GET(req: Request) {
  const url = new URL(req.url);
  const lane = url.searchParams.get("lane") || "ecosystem";
  const window = url.searchParams.get("window") || "all";
  const postType = url.searchParams.get("type") || "posts";
  const bucket = url.searchParams.get("bucket") || "";
  const page = url.searchParams.get("page") || "1";
  const limit = url.searchParams.get("limit") || "24";

  const cacheKey = `${lane}:${window}:${postType}:${bucket}:${page}:${limit}`;
  const hit = cache.get(cacheKey);
  if (hit && Date.now() - hit.at < CACHE_TTL_MS) {
    return NextResponse.json(hit.data, {
      headers: { "cache-control": "public, max-age=120" },
    });
  }

  const baseUrl = process.env.METEORA_INTEL_URL?.replace(/\/$/, "");
  if (!baseUrl) {
    return NextResponse.json(
      { count: 0, posts: [], hasMore: false, error: "METEORA_INTEL_URL not set" },
      { status: 200 },
    );
  }

  const params = new URLSearchParams({
    lane,
    window,
    type: postType,
    page,
    limit,
  });
  if (bucket) params.set("bucket", bucket);

  try {
    const res = await fetch(`${baseUrl}/api/feed?${params}`, {
      headers: { accept: "application/json" },
      signal: AbortSignal.timeout(8000),
    });
    if (!res.ok) {
      return NextResponse.json(
        { count: 0, posts: [], hasMore: false, error: `upstream ${res.status}` },
        { status: 200 },
      );
    }
    const data = (await res.json()) as FeedResponse;
    cache.set(cacheKey, { data, at: Date.now() });
    return NextResponse.json(data, {
      headers: { "cache-control": "public, max-age=120" },
    });
  } catch (err) {
    return NextResponse.json(
      { count: 0, posts: [], hasMore: false, error: String(err) },
      { status: 200 },
    );
  }
}

/** Text / handle anchors for “this is Meteora ecosystem,” including screener pads. */

export const SCREENER_PAD_HANDLES = new Set(
  [
    "embercurve",
    "lfowndotfun",
    "getstonkoptions",
    "stardotfun",
    "bagsapp",
    "perpspadfun",
    "clawpumptech",
    "ethicslaunch",
    "revshare_app",
    "otc_labs",
  ].map((h) => h.toLowerCase()),
);

const ECOSYSTEM_TEXT_RE =
  /solana|\$sol|meteora|@meteoraag|@meteoraeco|@vesper792|vesper|dbc|damm|dlmm|invent|embercurve|ember curve|lfown|letsfuckingown|bags\.fm|bagsapp|perpspad|clawpump|stonkoptions|star\.fun|ethics\.ltd|ethicslaunch|revshare|otcdesks|otc.?labs/;

export function hasEcosystemAnchor(text: string, username?: string): boolean {
  const handle = (username ?? "").toLowerCase().replace(/^@/, "");
  if (handle && SCREENER_PAD_HANDLES.has(handle)) return true;
  if (handle === "vesper792" || handle === "meteoraag" || handle === "meteoraeco") return true;
  return ECOSYSTEM_TEXT_RE.test(text.toLowerCase());
}

export function isLpArmyNoise(text: string): boolean {
  return /\blp\s*army\b|\blparmy\b|\$lparmy/.test(text.toLowerCase());
}

