"use client";

import { useCallback, useEffect, useRef, useState } from "react";

/**
 * Live X embeds of intel-ranked post IDs. Deleted tweets fail to embed and
 * vanish; edits show whatever X is serving now.
 */

type Post = {
  id: string;
  url: string;
};

type FeedData = {
  count: number;
  posts: Post[];
  hasMore?: boolean;
  error?: string;
};

const PAGE = 12;

const WINDOWS = [
  { id: "all", label: "All" },
  { id: "today", label: "Today" },
  { id: "week", label: "This week" },
] as const;

type Lane = "ecosystem" | "official";
type PostType = "posts" | "replies";

declare global {
  interface Window {
    twttr?: {
      ready: (cb: () => void) => void;
      widgets: {
        createTweet: (
          id: string,
          el: HTMLElement,
          opts?: Record<string, unknown>,
        ) => Promise<HTMLElement | undefined>;
      };
    };
  }
}

let widgetsPromise: Promise<boolean> | null = null;

function loadWidgets(): Promise<boolean> {
  if (typeof window === "undefined") return Promise.resolve(false);
  if (window.twttr?.widgets) return Promise.resolve(true);
  if (widgetsPromise) return widgetsPromise;
  widgetsPromise = new Promise((resolve) => {
    const existing = document.querySelector(
      'script[src="https://platform.twitter.com/widgets.js"]',
    );
    const finish = () => {
      if (window.twttr?.ready) {
        window.twttr.ready(() => resolve(Boolean(window.twttr?.widgets)));
        return;
      }
      resolve(Boolean(window.twttr?.widgets));
    };
    if (existing) {
      finish();
      return;
    }
    const s = document.createElement("script");
    s.src = "https://platform.twitter.com/widgets.js";
    s.async = true;
    s.onload = finish;
    s.onerror = () => resolve(false);
    document.head.appendChild(s);
  });
  return widgetsPromise;
}

function TweetEmbed({ id, url }: { id: string; url: string }) {
  const ref = useRef<HTMLDivElement>(null);
  const [state, setState] = useState<"loading" | "live" | "gone" | "link">("loading");

  useEffect(() => {
    let cancelled = false;
    const el = ref.current;
    if (!el) return;
    el.replaceChildren();
    void (async () => {
      const ok = await loadWidgets();
      if (cancelled) return;
      if (!ok || !window.twttr?.widgets) {
        setState("link");
        return;
      }
      try {
        const node = await window.twttr.widgets.createTweet(id, el, {
          theme: "dark",
          dnt: true,
          conversation: "none",
          align: "center",
        });
        if (cancelled) return;
        if (!node) {
          setState("gone");
          return;
        }
        setState("live");
      } catch {
        if (!cancelled) setState("link");
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [id]);

  if (state === "gone") return null;

  return (
    <article className="eco-card">
      {state === "link" ? (
        <a
          href={url}
          target="_blank"
          rel="noopener noreferrer"
          className="eco-embed-fallback"
        >
          Open post on X
        </a>
      ) : null}
      <div
        ref={ref}
        className="eco-embed"
        hidden={state === "link"}
        data-tweet-id={id}
      />
    </article>
  );
}

export function EcosystemFeed() {
  const [posts, setPosts] = useState<Post[]>([]);
  const [count, setCount] = useState(0);
  const [loading, setLoading] = useState(false);
  const [loadingMore, setLoadingMore] = useState(false);
  const [hasMore, setHasMore] = useState(false);
  const [loaded, setLoaded] = useState(false);
  const [lane, setLane] = useState<Lane>("ecosystem");
  const [window, setWindow] = useState<string>("all");
  const [postType, setPostType] = useState<PostType>("posts");
  const pageRef = useRef(1);
  const loadingMoreRef = useRef(false);
  const sectionRef = useRef<HTMLElement>(null);
  const sentinelRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (loaded) return;
    const el = sectionRef.current;
    if (!el) return;
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0]?.isIntersecting) {
          setLoaded(true);
          observer.disconnect();
        }
      },
      { rootMargin: "200px" },
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, [loaded]);

  const fetchPage = useCallback(
    async (nextPage: number, append: boolean) => {
      if (append) {
        setLoadingMore(true);
        loadingMoreRef.current = true;
      } else {
        setLoading(true);
        loadingMoreRef.current = false;
      }
      const params = new URLSearchParams({
        lane,
        window,
        type: postType,
        page: String(nextPage),
        limit: String(PAGE),
      });
      try {
        const res = await fetch(`/api/ecosystem-feed?${params}`, {
          cache: "no-store",
        });
        const data = (await res.json()) as FeedData;
        const incoming = data.posts || [];
        setPosts((prev) => (append ? [...prev, ...incoming] : incoming));
        setCount(data.count || 0);
        setHasMore(Boolean(data.hasMore));
        pageRef.current = nextPage;
      } catch {
        if (!append) {
          setPosts([]);
          setCount(0);
          setHasMore(false);
        }
      } finally {
        setLoading(false);
        setLoadingMore(false);
        loadingMoreRef.current = false;
      }
    },
    [lane, window, postType],
  );

  useEffect(() => {
    if (!loaded) return;
    void fetchPage(1, false);
  }, [loaded, fetchPage]);

  useEffect(() => {
    if (!loaded) return;
    const tick = window.setInterval(() => {
      if (pageRef.current !== 1 || loadingMoreRef.current) return;
      void fetchPage(1, false);
    }, 30_000);
    return () => window.clearInterval(tick);
  }, [loaded, fetchPage]);

  useEffect(() => {
    if (!loaded || !hasMore || loading || loadingMore) return;
    const node = sentinelRef.current;
    if (!node) return;
    const io = new IntersectionObserver(
      (entries) => {
        if (!entries.some((e) => e.isIntersecting)) return;
        if (loadingMoreRef.current) return;
        loadingMoreRef.current = true;
        void fetchPage(pageRef.current + 1, true);
      },
      { root: null, rootMargin: "160px 0px", threshold: 0 },
    );
    io.observe(node);
    return () => io.disconnect();
  }, [loaded, hasMore, loading, loadingMore, fetchPage, posts.length]);

  const status =
    lane === "official"
      ? count === 1
        ? "1 official"
        : `${count} official`
      : count === 1
        ? "1 post"
        : `${count} posts`;

  return (
    <section className="eco-feed" ref={sectionRef} aria-label="Meteora Ecosystem feed">
      <h2 className="eco-feed-heading">Meteora Ecosystem feed</h2>
      <div className="eco-feed-bar">
        <p className="eco-feed-status">
          {loaded && !loading ? status : "Feed"}
          <span className="eco-feed-dot" aria-hidden="true" />
        </p>
        {loaded && (
          <div className="eco-feed-toggles">
            <div className="eco-tabs" role="tablist" aria-label="Lane">
              {(["ecosystem", "official"] as Lane[]).map((l) => (
                <button
                  key={l}
                  type="button"
                  role="tab"
                  aria-selected={lane === l}
                  className={`eco-tab ${lane === l ? "is-active" : ""}`}
                  onClick={() => setLane(l)}
                >
                  {l === "official" ? "Official" : "Ecosystem"}
                </button>
              ))}
            </div>
            <div className="eco-type-toggle" role="tablist" aria-label="Post type">
              {(["posts", "replies"] as PostType[]).map((t) => (
                <button
                  key={t}
                  type="button"
                  role="tab"
                  aria-selected={postType === t}
                  className={`eco-type-opt ${postType === t ? "is-active" : ""}`}
                  onClick={() => setPostType(t)}
                >
                  {t}
                </button>
              ))}
