/**
 * Twitter for Websites (widgets.js) — official loader + hydrate.
 * @see https://developer.x.com/en/docs/x-for-websites/javascript-api/guides/set-up-twitter-for-websites
 */

export type Twttr = {
  ready: (cb: (twttr: Twttr) => void) => void;
  widgets: {
    load: (el?: HTMLElement) => void;
    createTweet: (
      id: string,
      el: HTMLElement,
      opts?: Record<string, unknown>,
    ) => Promise<HTMLElement | undefined>;
  };
  events: {
    bind: (name: string, cb: (ev: { target?: HTMLElement }) => void) => void;
  };
  _e?: Array<(twttr: Twttr) => void>;
};

declare global {
  interface Window {
    twttr?: Twttr;
  }
}

const WIDGETS_SRC = "https://platform.twitter.com/widgets.js";
let eventsBound = false;

/** Canonical status URL — widgets/oEmbed still expect twitter.com, not x.com. */
export function twitterStatusUrl(url: string, id: string): string {
  try {
    const parsed = new URL(url);
    parsed.hostname = "twitter.com";
    return parsed.toString();
  } catch {
    return `https://twitter.com/i/status/${id}`;
  }
}

/**
 * Exact bootstrap from Twitter for Websites: queue `ready()` before the
 * script arrives, inject `#twitter-wjs` once.
 */
export function ensureXWidgets(): Promise<Twttr> {
  if (typeof window === "undefined") {
    return Promise.reject(new Error("no window"));
  }

  const existing = window.twttr;
  if (!existing || !existing.ready) {
    window.twttr = {
      _e: [],
      ready(f: (twttr: Twttr) => void) {
        (window.twttr?._e ?? []).push(f);
      },
      widgets: existing?.widgets ?? ({} as Twttr["widgets"]),
      events: existing?.events ?? ({} as Twttr["events"]),
    };
  }

  if (!document.getElementById("twitter-wjs")) {
    const js = document.createElement("script");
    js.id = "twitter-wjs";
    js.src = WIDGETS_SRC;
    js.async = true;
    document.body.appendChild(js);
  }

  return new Promise((resolve) => {
    window.twttr!.ready((twttr) => {
      bindUnavailableHider(twttr);
      resolve(twttr);
    });
  });
}

function bindUnavailableHider(twttr: Twttr) {
  if (eventsBound || !twttr.events?.bind) return;
  eventsBound = true;
  twttr.events.bind("rendered", (ev) => {
    const node = ev.target;
    if (!node) return;
    const text = (node.textContent || "").toLowerCase();
    if (
      text.includes("this post is unavailable") ||
      text.includes("this tweet is unavailable")
    ) {
      const wrap = node.closest(".eco-embed");
      if (wrap instanceof HTMLElement) wrap.hidden = true;
    }
  });
}

/** Hydrate any new `blockquote.twitter-tweet` nodes in a container. */
export async function hydrateXEmbeds(container: HTMLElement | null) {
  if (!container) return;
  const twttr = await ensureXWidgets();
  twttr.widgets?.load?.(container);
}

/**
 * Twitter for Websites (widgets.js) — official loader + hydrate.
 * @see https://developer.x.com/en/docs/x-for-websites/javascript-api/guides/set-up-twitter-for-websites
 */

type ReadyFn = (twttr: Twttr) => void;

export type Twttr = {
  ready: (cb: ReadyFn) => void;
  widgets?: {
    load: (el?: HTMLElement) => void;
    createTweet?: (
      id: string,
      el: HTMLElement,
      opts?: Record<string, unknown>,
    ) => Promise<HTMLElement | undefined>;
  };
  events?: {
    bind: (name: string, cb: (ev: { target?: HTMLElement }) => void) => void;
  };
  _e?: ReadyFn[];
};

declare global {
  interface Window {
    twttr?: Twttr;
  }
}

const WIDGETS_SRC = "https://platform.twitter.com/widgets.js";
let eventsBound = false;

/** Canonical status URL — widgets/oEmbed still expect twitter.com, not x.com. */
export function twitterStatusUrl(url: string, id: string): string {
  try {
    const parsed = new URL(url);
    parsed.hostname = "twitter.com";
    return parsed.toString();
  } catch {
    return `https://twitter.com/i/status/${id}`;
  }
}

/**
 * Official bootstrap: queue `ready()` before widgets.js, inject `#twitter-wjs` once.
 */
function installOfficialLoader(): Twttr {
  const t: Twttr = window.twttr || { _e: [], ready: (f: ReadyFn) => undefined };
  window.twttr = (function (d: Document, s: string, id: string) {
    const fjs = d.getElementsByTagName(s)[0];
    const acc = window.twttr || t;
    acc._e = acc._e || [];
    acc.ready =
      acc.ready ||
      function (f: ReadyFn) {
        acc._e!.push(f);
      };
    if (d.getElementById(id)) return acc;
    const js = d.createElement(s) as HTMLScriptElement;
    js.id = id;
    js.src = WIDGETS_SRC;
    js.async = true;
    fjs.parentNode?.insertBefore(js, fjs);
    return acc;
  })(document, "script", "twitter-wjs");
  return window.twttr!;
}

export function ensureXWidgets(): Promise<Twttr> {
  if (typeof window === "undefined") {
    return Promise.reject(new Error("no window"));
  }
  const twttr = installOfficialLoader();
  return new Promise((resolve) => {
    twttr.ready((readyTwttr) => {
      bindUnavailableHider(readyTwttr);
      resolve(readyTwttr);
    });
  });
}

function bindUnavailableHider(twttr: Twttr) {
  if (eventsBound || !twttr.events?.bind) return;
  eventsBound = true;
  twttr.events.bind("rendered", (ev) => {
    const node = ev.target;
    if (!node) return;
    const text = (node.textContent || "").toLowerCase();
    if (
      text.includes("this post is unavailable") ||
      text.includes("this tweet is unavailable")
    ) {
      const wrap = node.closest(".eco-embed");
      if (wrap instanceof HTMLElement) wrap.hidden = true;
    }
  });
}

/** Hydrate any new `blockquote.twitter-tweet` nodes in a container. */
export async function hydrateXEmbeds(container: HTMLElement | null) {
  if (!container) return;
  const twttr = await ensureXWidgets();
  twttr.widgets?.load?.(container);
}

