type PostType = "posts" | "replies";

declare global {
  interface Window {
    twttr?: {
      ready: (cb: () => void) => void;
      widgets: {
        createTweet: (
          id: string,
          el: HTMLElement,
          opts?: Record<string, unknown>,
        ) => Promise<HTMLElement | undefined>;
      };
    };
  }
