let widgetsPromise: Promise<boolean> | null = null;

function loadWidgets(): Promise<boolean> {
  if (typeof window === "undefined") return Promise.resolve(false);
  if (window.twttr?.widgets) return Promise.resolve(true);
  if (widgetsPromise) return widgetsPromise;
  widgetsPromise = new Promise((resolve) => {
    const existing = document.querySelector(
      'script[src="https://platform.twitter.com/widgets.js"]',
    );
    const finish = () => {
      if (window.twttr?.ready) {
        window.twttr.ready(() => resolve(Boolean(window.twttr?.widgets)));
        return;
      }
      resolve(Boolean(window.twttr?.widgets));
    };
    if (existing) {
      finish();
      return;
    }
    const s = document.createElement("script");
    s.src = "https://platform.twitter.com/widgets.js";
    s.async = true;
    s.onload = finish;
    s.onerror = () => resolve(false);
    document.head.appendChild(s);
  });
  return widgetsPromise;
}

function TweetEmbed({ id, url }: { id: string; url: string }) {
  const ref = useRef<HTMLDivElement>(null);
  const [state, setState] = useState<"loading" | "live" | "gone" | "link">("loading");

  useEffect(() => {
    let cancelled = false;
    const el = ref.current;
    if (!el) return;
    el.replaceChildren();
    void (async () => {
      const ok = await loadWidgets();
      if (cancelled) return;
      if (!ok || !window.twttr?.widgets) {
        setState("link");
        return;
      }
      try {
        const node = await window.twttr.widgets.createTweet(id, el, {
          theme: "dark",
          dnt: true,
          conversation: "none",
          align: "center",
        });
        if (cancelled) return;
        if (!node) {
          setState("gone");
          return;
        }
        setState("live");
      } catch {
        if (!cancelled) setState("link");
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [id]);

  if (state === "gone") return null;

  return (
    <article className="eco-card">
      {state === "link" ? (
        <a
          href={url}
          target="_blank"
          rel="noopener noreferrer"
          className="eco-embed-fallback"
        >
          Open post on X
        </a>
      ) : null}
      <div
        ref={ref}
        className="eco-embed"
        hidden={state === "link"}
        data-tweet-id={id}
      />
    </article>
  );
}

