/**
 * Twitter for Websites — official `#twitter-wjs` loader, then
 * `widgets.load` / `createTweet` for SPA inserts.
 * @see https://developer.x.com/en/docs/x-for-websites/javascript-api/guides/set-up-twitter-for-websites
 */

type ReadyFn = (twttr: Twttr) => void;

export type Twttr = {
  ready: (cb: ReadyFn) => void;
  widgets?: {
    load: (el?: HTMLElement) => void;
    createTweet: (
      id: string,
      el: HTMLElement,
      opts?: Record<string, unknown>,
    ) => Promise<HTMLElement | undefined>;
  };
  events?: {
    bind: (name: string, cb: (ev: { target?: HTMLElement }) => void) => void;
  };
  _e?: ReadyFn[];
};

declare global {
  interface Window {
    twttr?: Twttr;
  }
}

const WIDGETS_SRC = "https://platform.twitter.com/widgets.js";
let eventsBound = false;
let widgetsPromise: Promise<Twttr> | null = null;

/** Canonical status URL — widgets/oEmbed still expect twitter.com, not x.com. */
export function twitterStatusUrl(url: string, id: string): string {
  try {
    const parsed = new URL(url);
    parsed.hostname = "twitter.com";
    return parsed.toString();
  } catch {
    return `https://twitter.com/i/status/${id}`;
  }
}

function installOfficialLoader() {
  const existing = document.getElementById("twitter-wjs");
  if (!window.twttr) {
    const stub: Twttr = {
      _e: [],
      ready(f: ReadyFn) {
        stub._e!.push(f);
      },
    };
    window.twttr = stub;
  }
  if (existing) return;
  const fjs = document.getElementsByTagName("script")[0];
  const js = document.createElement("script");
  js.id = "twitter-wjs";
  js.src = WIDGETS_SRC;
  js.async = true;
  fjs?.parentNode?.insertBefore(js, fjs);
}

function widgetsReady(twttr: Twttr | undefined): twttr is Twttr {
  return Boolean(twttr?.widgets?.load && twttr.widgets.createTweet);
}

export function ensureXWidgets(): Promise<Twttr> {
  if (typeof window === "undefined") {
    return Promise.reject(new Error("no window"));
  }
  if (widgetsPromise) return widgetsPromise;
  widgetsPromise = new Promise((resolve, reject) => {
    installOfficialLoader();
    const finish = () => {
      const t = window.twttr;
      if (!widgetsReady(t)) return false;
      bindUnavailableHider(t);
      resolve(t);
      return true;
    };
    if (finish()) return;
    window.twttr?.ready?.(() => {
      finish();
    });
    const js = document.getElementById("twitter-wjs");
    js?.addEventListener("load", () => {
      window.setTimeout(() => {
        if (!finish()) {
          reject(new Error("widgets.js loaded without factory functions"));
        }
      }, 0);
    });
    js?.addEventListener("error", () => {
      reject(new Error("widgets.js failed to load"));
    });
  });
  return widgetsPromise;
}

function bindUnavailableHider(twttr: Twttr) {
  if (eventsBound || !twttr.events?.bind) return;
  eventsBound = true;
  twttr.events.bind("rendered", (ev) => {
    const node = ev.target;
    if (!node) return;
    const text = (node.textContent || "").toLowerCase();
    if (
      text.includes("this post is unavailable") ||
      text.includes("this tweet is unavailable")
    ) {
      const wrap = node.closest(".eco-embed");
      if (wrap instanceof HTMLElement) wrap.hidden = true;
    }
  });
}

const TWEET_OPTS = {
  theme: "dark",
  dnt: true,
  conversation: "none",
  width: 550,
  align: "center",
} as const;

/**
 * Hydrate Publish-style blockquotes, then factory-create any that widgets.js
 * left as plain HTML (typical in SPAs / infinite scroll).
 */
export async function hydrateXEmbeds(container: HTMLElement | null) {
  if (!container?.querySelector(".twitter-tweet, [data-tweet-id]")) return;
  const twttr = await ensureXWidgets();
  twttr.widgets?.load?.(container);

  const wraps = container.querySelectorAll<HTMLElement>(".eco-embed");
  for (const wrap of wraps) {
    if (wrap.hidden) continue;
    if (wrap.querySelector("iframe, twitter-widget, .twitter-tweet-rendered")) {
      continue;
    }
    const id = wrap.dataset.tweetId;
    const mount = wrap.querySelector<HTMLElement>(".eco-embed-mount");
    if (!id || !mount || !twttr.widgets?.createTweet) continue;
    try {
      const node = await twttr.widgets.createTweet(id, mount, TWEET_OPTS);
      if (!node) {
        wrap.hidden = true;
        continue;
      }
      wrap.querySelector("blockquote")?.remove();
    } catch {
      /* keep the status link in the blockquote */
    }
  }
}

