function TweetEmbed({ id, url }: { id: string; url: string }) {
  const href = twitterStatusUrl(url, id);
  const wrapRef = useRef<HTMLDivElement>(null);
  const [active, setActive] = useState(false);
  const [height, setHeight] = useState(() => heightCache.get(id) ?? 280);

  useEffect(() => {
    const el = wrapRef.current;
    if (!el) return;
    const io = new IntersectionObserver(
      ([entry]) => {
        setActive(Boolean(entry?.isIntersecting));
      },
      { root: null, rootMargin: "120px 0px", threshold: 0.01 },
    );
    io.observe(el);
    return () => io.disconnect();
  }, [id]);

  useEffect(() => {
    if (!active) return;
    const onMsg = (event: MessageEvent) => {
      const origin = event.origin || "";
      if (
        !origin.includes("twitter.com") &&
        !origin.includes("x.com") &&
        !origin.includes("twimg.com")
      ) {
        return;
      }
      const frame = wrapRef.current?.querySelector("iframe");
      if (!frame || event.source !== frame.contentWindow) return;
      let payload: unknown = event.data;
      if (typeof payload === "string") {
        try {
          payload = JSON.parse(payload);
        } catch {
          return;
        }
      }
      if (!payload || typeof payload !== "object") return;
      const rec = payload as { params?: { height?: number }; height?: number };
      const next = rec.params?.height ?? rec.height;
      if (!next || next < 80) return;
      const rounded = Math.ceil(next);
      heightCache.set(id, rounded);
      setHeight((h) => (h === rounded ? h : rounded));
    };
    window.addEventListener("message", onMsg);
    return () => window.removeEventListener("message", onMsg);
  }, [active, id]);

  return (
    <div
      ref={wrapRef}
      className="eco-embed"
      data-tweet-id={id}
      style={{ minHeight: height }}
